mapper.select:
SELECT DISTINCT PTL_PORTFOLIO.PORTFOLIO_ID id, PTL_PORTFOLIO.PORTFOLIO_ID || ':' || PTL_PORTFOLIO.PORTFOLIO_NAME text FROM PTL_PORTFOLIO LEFT JOIN PTL_SEC_ACCT ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_SEC_ACCT.PORTFOLIO_ID
INVEST_YESORNO = 'Y' AND PORTFOLIO_TYPE = '01'
AND PTL_PORTFOLIO.PORTFOLIO_ID != #{portfolioIdOut}
AND PTL_SEC_ACCT.ACCT_NO = #{secManageAcctId}
AND (PTL_PORTFOLIO.PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND PTL_PORTFOLIO.PORTFOLIO_ID = #{initValue}

SELECT NVL(SUM(DECODE(PTL_SEC_POSITION.HODING_TYPE,
        #{HODING_TYPE_03},PTL_SEC_POSITION.AMOUNT,
        #{HODING_TYPE_05}, PTL_SEC_POSITION.AMOUNT,
        #{HODING_TYPE_06}, -1 * PTL_SEC_POSITION.AMOUNT,
        #{HODING_TYPE_04}, -1 * PTL_SEC_POSITION.AMOUNT)) * 100,0)
FROM PTL_SEC_POSITION


        AND PTL_SEC_POSITION.PORTFOLIO_ID = #{portfolioId}


        AND PTL_SEC_POSITION.FINPROD_ID = #{finprodId}


        AND PTL_SEC_POSITION.SEC_ACCT_ID = #{secAcctId}


        AND PTL_SEC_POSITION.SEC_ACCT_ID = #{chlId}


        AND PTL_SEC_POSITION.CDATE = TO_DATE(#{cdate},'yyyy-MM-dd')

SELECT NVL(AMOUNT,0)
FROM PTL_SEC_POSITION_DETAIL


        AND CDATE = TO_DATE(#{cdate},'yyyy-MM-dd')


        AND FINPROD_ID = #{finprodId}


        AND TRADE_ID = #{tradeId}

SELECT NVL(AMOUNT,0) FROM PTL_SEC_POSITION
AND CDATE = TO_DATE(#{cdate},'yyyy-MM-dd')
AND FINPROD_ID = #{tradeId}
